def two_sum(nums, target):
    m = {}
    for i, n in enumerate(nums):
        if target - n in m:
            return [m[target - n], i]
        m[n] = i
    return []

def ngram_tokens(text, n):
    words = text.split()
    return [tuple(words[i:i+n]) for i in range(len(words) - n + 1)]

import re
from collections import Counter
def word_freq(sentence):
    words = re.findall(r'[A-Za-z0-9]+', sentence.lower())
    return dict(Counter(words))

def remove_duplicates(lst):
    seen = set()
    out = []
    for x in lst:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

def gcd(a, b):
    while b:
        a, b = b, a % b
    return abs(a)

def count_chars(s):
    letters = sum(c.isalpha() for c in s)
    digits = sum(c.isdigit() for c in s)
    spaces = sum(c.isspace() for c in s)
    others = len(s) - letters - digits - spaces
    return {"letters": letters, "digits": digits, "spaces": spaces, "others": others}

def is_balanced(s):
    pairs = {')': '(', ']': '['}
    stack = []
    for ch in s:
        if ch in '([':
            stack.append(ch)
        elif ch in ')]':
            if not stack or stack.pop() != pairs[ch]:
                return False
    return len(stack) == 0

def fib(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a
